"""Mutalia-e-Quran XII PDF91: p.88 — Surah al-Nur heading; verses 24:1–8. Run: python class12_quran_page091.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p91():
    b = Builder()
    b.h('Surah al-Nur (24) — Madani; order of revelation 102; verses 64, sections 9', 'سُوْرَةُ النُّوْرِ ۲۴ — مَدَنِيَّةٌ ۱۰۲ — اٰیَاتُهَا ۶۴، رُکُوْعَاتُهَا ۹', 'سورة النور (۲۴) — مدني؛ د نزول ترتیب ۱۰۲؛ آیتونه ۶۴، رکوعونه ۹')
    b.p('بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\nIn the name of Allah, the Beneficent, the Merciful.', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\nاللہ کے نام سے شروع جو بڑا مہربان نہایت رحم فرمانے والا ہے', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\nد الله په نوم پیل چې ډېر مهربان، بې‌حده رحم کوونکی دی')
    b.paras[-1]['arabicSource'] = True
    V(b, 24, 1, '(یہ) ایک سورت ہے جسے ہم نے نازل کیا ہے اور اس (کے احکام) کو ہم نے فرض کیا ہے اور ہم نے اس میں واضح آیات نازل فرمائی ہیں تاکہ تم نصیحت حاصل کرو۔',
      '(دا) یو سورت دی چې موږ نازل کړی او د هغه (حکمونه) مو فرض کړي، او موږ پکې ښکاره آیتونه نازل کړي تر څو تاسو نصیحت واخلئ.')
    V(b, 24, 2, 'زنا کرنے والی عورت اور زنا کرنے والا مرد ان دونوں میں سے ہر ایک کو سو کوڑے لگاؤ اور تمھیں اللہ کے دین کے معاملے میں ان دونوں پر ذرا ترس نہ آئے اگر تم اللہ اور آخرت کے دن پر ایمان رکھتے ہو اور چاہیے کہ مومنوں کی ایک جماعت ان دونوں کی سزا (کے موقع) پر موجود رہے۔',
      'زنا کوونکې ښځه او زنا کوونکی نارینه، له دې دواړو هر یوه ته سل دُرې ووهئ، او د الله د دین په چاره کې دې پر دواړو هېڅ زړه سوی ونه کړئ که پر الله او د آخرت پر ورځ ایمان لرئ؛ او باید د مؤمنانو یوه ډله د دواړو د سزا (پر مهال) حاضره وي.')
    V(b, 24, 3, 'زانی مرد صرف زناکار یا مشرکہ عورت (ہی) سے نکاح (کرنا پسند) کرے گا اور زانیہ عورت صرف زانی یا مشرک مرد (ہی) سے نکاح (کرنا پسند) کرے گی اور مومنوں پر یہ حرام کیا گیا ہے۔',
      'زاني نارینه به یوازې له زناکارې یا مشرکې ښځې سره نکاح (خوښوي)، او زانیه ښځه به یوازې له زاني یا مشرک نارینه سره نکاح (خوښوي)؛ او پر مؤمنانو دا حرام کړای شوی.')
    V(b, 24, 4, 'اور وہ لوگ جو پاک دامن عورتوں پر (زنا کی) تہمت لگائیں پھر (اس پر) چار گواہ نہ پیش کر سکیں تو اُن کو اسی کوڑے لگاؤ اور کبھی بھی اُن کی کوئی گواہی قبول نہ کرو اور وہی لوگ فاسق ہیں۔',
      'او هغه کسان چې پر پاکلمنو ښځو د (زنا) تور ولګوي، بیا (پرې) څلور شاهدان وړاندې نه کړای شي، نو هغوی ته اتیا دُرې ووهئ، او هېڅکله یې کومه شاهدي مه منئ؛ او همدوی فاسقان دي.')
    V(b, 24, 5, 'مگر وہ لوگ جو اس کے بعد توبہ کر لیں اور (اپنی) اصلاح کر لیں تو بے شک اللہ بڑا ہی بخشنے والا نہایت رحم فرمانے والا ہے۔',
      'مګر هغه کسان چې له دې وروسته توبه وکړي او (ځانونه) سم کړي، نو بې‌شکه الله ډېر بښونکی، بې‌حده مهربان دی.')
    V(b, 24, 6, 'اور وہ لوگ جو اپنی بیویوں پر (زنا کی) تہمت لگائیں اور اُن کے پاس خود ان کے سوا کوئی گواہ نہ ہو تو ان میں سے ایسے کسی شخص کی گواہی یہ ہے کہ (وہ) چار بار اللہ کی قسم کھا کر گواہی دے کہ یقیناً وہ (اس لگائے ہوئے الزام میں) سچا ہے۔',
      'او هغه کسان چې پر خپلو مېرمنو د (زنا) تور ولګوي او له ځانونو پرته یې بل شاهد نه وي، نو له هغوی د داسې کس شاهدي دا ده چې څلور ځله په الله قسم وخوري او شاهدي ورکړي چې یقیناً هغه (په لګولي تور کې) رښتینی دی.')
    V(b, 24, 7, 'اور پانچویں بار یہ (کہے) کہ اُس پر اللہ کی لعنت ہو اگر وہ جھوٹا ہو۔',
      'او پنځم ځل دې (ووایي) چې پر هغه دې د الله لعنت وي که درواغجن وي.')
    V(b, 24, 8, 'اور اس عورت سے (بھی) یہ بات (زنا کی) سزا کو ٹال سکتی ہے کہ وہ چار بار اللہ کی قسم کھا کر گواہی دے کہ وہ (شوہر) یقیناً (اس الزام میں) جھوٹا ہے۔',
      'او له هغې ښځې به هم دا خبره د (زنا) سزا لرې کړي چې څلور ځله په الله قسم وخوري او شاهدي ورکړي چې هغه (مېړه) یقیناً (په دې تور کې) درواغجن دی.')
    BOOK.save(91, [(9, rec(b, 9, 91, 91))], issues=[{'id': 'mq12-pdf091', 'unit': 9, 'printedPage': 88,
               'description': 'Surah heading prints order of revelation ۱۰۲, verses ۶۴, sections ۹ (as printed). Ruku sign after verse 5 not reproduced.'}])


if __name__ == '__main__':
    p91()
